#!/data/data/com.termux/files/usr/bin/bash
set -Eeuo pipefail
cd "$HOME/companyos"
source "$HOME/.companyos_launch_env" 2>/dev/null || true

STAMP="$(date +%Y%m%d_%H%M%S)"
BK="$HOME/companyos/.companyos_backups/semantic_capability_bridge_v13_$STAMP"
mkdir -p "$BK"
cp -a companyos/runtime/service_supervisor.py "$BK/" 2>/dev/null || true

echo "" | base64 -d > companyos/runtime/semantic_capability_bridge.py
echo "" | base64 -d > scripts/companyos_semanticctl
chmod +x scripts/companyos_semanticctl
echo "" | base64 -d > tests/test_semantic_capability_bridge_v13.py

echo "" | base64 -d > "$PREFIX/tmp/companyos_semantic_v13_patch.py"
python "$PREFIX/tmp/companyos_semantic_v13_patch.py"
rm -f "$PREFIX/tmp/companyos_semantic_v13_patch.py"

echo "[1/8] Compile"
python -m py_compile companyos/runtime/semantic_capability_bridge.py companyos/runtime/service_supervisor.py tests/test_semantic_capability_bridge_v13.py

echo "[2/8] Semantic bridge tests"
python -m unittest tests.test_semantic_capability_bridge_v13 -v

echo "[3/8] Current inventory"
scripts/companyos_expandctl inventory || true

echo "[4/8] Convert capability output into next guarded request"
scripts/companyos_semanticctl once | tee .companyos_runtime/capability_expansion/semantic_bridge_v13_first_cycle.json

echo "[5/8] Show queue"
scripts/companyos_compoundctl requests || true

echo "[6/8] Execute one new guarded capability request"
scripts/companyos_requestctl once | tee .companyos_runtime/capability_expansion/semantic_bridge_v13_execution.json || true
scripts/companyos_feedbackctl once || true

echo "[7/8] Commit/push"
git add companyos/runtime/semantic_capability_bridge.py companyos/runtime/service_supervisor.py scripts/companyos_semanticctl tests/test_semantic_capability_bridge_v13.py
git diff --cached --quiet || git commit -m "Bridge semantic capability outputs into recursive expansion"
BRANCH="$(git branch --show-current)"
[ -n "$BRANCH" ] && git push origin "$BRANCH" || true

echo "[8/8] Restart + verify"
scripts/companyosctl restart || true
sleep 8

echo "===== SEMANTIC BRIDGE ====="
scripts/companyos_semanticctl status || true
echo "===== REQUEST EXECUTOR ====="
scripts/companyos_requestctl status || true
echo "===== REQUESTS ====="
scripts/companyos_compoundctl requests || true
echo "===== INVENTORY ====="
scripts/companyos_expandctl inventory || true
echo "===== FEEDBACK ====="
scripts/companyos_feedbackctl status || true
echo "===== SERVICES ====="
scripts/companyosctl status || true

echo "BACKUP=$BK"
echo "COMPANYOS_SEMANTIC_OUTPUT_CAPABILITY_BRIDGE_V13=PASS"
